From f8460c389eef7a46034c4508a3ca1281324ea6de Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:31:56 +0100
Subject: [PATCH] applets/taskmanager: offer Close All for ungrouped windows of
 an app

When several windows of the same app were shown as separate tasks, the
context menu only had Close, so they had to be closed one by one. Now a
Close All item closes every window of that app, like a grouped task does.

BUG: 485095
---
 applets/taskmanager/qml/ContextMenu.qml | 37 +++++++++++++++++++++++++
 1 file changed, 37 insertions(+)

diff --git a/applets/taskmanager/qml/ContextMenu.qml b/applets/taskmanager/qml/ContextMenu.qml
index fe837049fc..b48ebb2c8c 100644
--- a/applets/taskmanager/qml/ContextMenu.qml
+++ b/applets/taskmanager/qml/ContextMenu.qml
@@ -869,4 +869,41 @@ PlasmaExtras.Menu {
             tasksModel.requestClose(menu.modelIndex);
         }
     }
+
+    PlasmaExtras.MenuItem {
+        id: closeAllSameAppItem
+
+        // Ungrouped windows of the same app, matched like TaskGroupingProxyModel does
+        readonly property list<var> sameAppTasks: {
+            if (!menu.visualParent || !menu.get(TaskManager.AbstractTasksModel.IsWindow)
+                || menu.get(TaskManager.AbstractTasksModel.IsGroupParent) || menu.modelIndex.parent.valid) {
+                return [];
+            }
+
+            const appId = menu.get(TaskManager.AbstractTasksModel.AppId);
+            const launcherUrl = menu.get(TaskManager.AbstractTasksModel.LauncherUrlWithoutIcon).toString();
+            const tasks = [];
+
+            for (let i = 0; i < tasksModel.count; ++i) {
+                const index = tasksModel.makeModelIndex(i);
+                if (!tasksModel.data(index, TaskManager.AbstractTasksModel.IsWindow)
+                    || !tasksModel.data(index, TaskManager.AbstractTasksModel.IsClosable)) {
+                    continue;
+                }
+                if ((appId && tasksModel.data(index, TaskManager.AbstractTasksModel.AppId) === appId)
+                    || (launcherUrl && tasksModel.data(index, TaskManager.AbstractTasksModel.LauncherUrlWithoutIcon).toString() === launcherUrl)) {
+                    tasks.push(tasksModel.makePersistentModelIndex(i));
+                }
+            }
+
+            return tasks;
+        }
+
+        visible: closeWindowItem.visible && sameAppTasks.length > 1
+
+        text: i18nc("@action:inmenu", "&Close All")
+        icon: "window-close"
+
+        onClicked: sameAppTasks.forEach(index => tasksModel.requestClose(index))
+    }
 }
-- 
